// JS/TS probe running inside the buggy revision
// Goal: record the out array values for NaN-containing inputs.

function BooleanArray(n){
  // stdlib's BooleanArray may not exist in the probe runtime; emulate if needed.
  return new Uint8Array(n);
}

const dcuevery = require('@stdlib/blas/ext/base/dcuevery');

// Try common calling conventions:
// Many stdlib ndarrays expose signature: dcuevery(x.length, x, stride, out, outStride)
// We'll build `out` as a typed array and also try stdlib BooleanArray if available.

let out0, out1;

function makeOut(n){
  // Prefer stdlib BooleanArray if present
  try {
    const BA = require('@stdlib/array/bool/ctor');
    // BA is a constructor factory sometimes; try to construct via `new`.
    return new (BA.default || BA)(n);
  } catch (e) {
    return new Uint8Array(n);
  }
}

const xs = [
  new Float64Array([1.0, NaN, 1.0, 1.0]),
  new Float64Array([NaN, NaN, NaN, NaN])
];

const outs = [makeOut(4), makeOut(4)];

// Call dcuevery for each case.
for (let i=0; i<2; i++){
  const x = xs[i];
  const out = outs[i];

  // signature candidates
  // (n, x, stride, y, incx?, incy?)
  // We'll attempt ndarray variant with: dcuevery(n, x, strideX, out, strideOut)
  // If the module expects 1-based dims or extra args, it will throw; we'll try alternate forms.
  let ok=false;
  try {
    dcuevery(x.length, x, 1, out, 1);
    ok=true;
  } catch (e1){
    try {
      dcuevery(x.length, x, 1, out, 1, 0, 0);
      ok=true;
    } catch (e2){
      // last try
      dcuevery(x.length, x, 0, out, 1);
      ok=true;
    }
  }

  // Normalize out to plain JS array of booleans.
  // For Uint8Array: 0/1.
  // For stdlib BooleanArray: it may be array-like.
  let arr = [];
  for (let k=0;k<4;k++){
    const v = out[k];
    arr.push(v === true || v === 1 || v === '1');
  }

  if (i===0) out0 = arr;
  if (i===1) out1 = arr;
}

probe('out_case1', out0);
probe('out_case2', out1);

